:root {
  --color-bg: #1e1e2f;
  --color-card: #2a2a40;
  --color-primary: #6c63ff;
  --color-accent: #ff6584;
  --color-text: #f0f0f5;
  --color-cell: #3a3a55;
  --color-robot: #ffd166;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font);
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.card {
  background: var(--color-card);
  border-radius: 1.5rem;
  padding: 2rem 1.5rem;
  max-width: 500px;
  width: 100%;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.25rem;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: var(--color-primary);
}

.subtitle {
  font-size: 1rem;
  color: #b0b0c0;
  margin-top: -0.5rem;
}

.status {
  display: flex;
  gap: 1.5rem;
  font-size: 1rem;
  font-weight: 500;
  background: rgba(0, 0, 0, 0.2);
  padding: 0.5rem 1rem;
  border-radius: 0.75rem;
  flex-wrap: wrap;
  justify-content: center;
}

.board {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 4px;
  background: var(--color-bg);
  padding: 4px;
  border-radius: 0.75rem;
  width: 100%;
  aspect-ratio: 1 / 1;
  max-width: 400px;
}

.cell {
  background: var(--color-cell);
  border-radius: 0.4rem;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  transition: background 0.15s ease;
  position: relative;
}

.cell.robot {
  background: var(--color-robot);
  box-shadow: 0 0 12px var(--color-robot);
}

.cell.robot::after {
  content: '';
  display: block;
  width: 60%;
  height: 60%;
  background: #2a2a40;
  border-radius: 50%;
  position: absolute;
}

.cell.robot::before {
  content: '';
  display: block;
  width: 0;
  height: 0;
  border-left: 12px solid transparent;
  border-right: 12px solid transparent;
  border-bottom: 18px solid var(--color-accent);
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) rotate(0deg);
  z-index: 1;
}

.cell.robot[data-dir="right"]::before { transform: translate(-50%, -50%) rotate(90deg); }
.cell.robot[data-dir="down"]::before { transform: translate(-50%, -50%) rotate(180deg); }
.cell.robot[data-dir="left"]::before { transform: translate(-50%, -50%) rotate(270deg); }
.cell.robot[data-dir="up"]::before { transform: translate(-50%, -50%) rotate(0deg); }

.controls {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.75rem;
  width: 100%;
  max-width: 400px;
}

.control-btn {
  background: var(--color-primary);
  color: white;
  border: none;
  border-radius: 0.75rem;
  padding: 0.85rem 0.5rem;
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease;
  box-shadow: 0 4px 0 #4a44b0;
  min-height: 48px;
}

.control-btn:hover {
  background: #7b73ff;
}

.control-btn:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.control-btn:active {
  transform: translateY(3px);
  box-shadow: 0 1px 0 #4a44b0;
}

.control-btn.reset {
  background: var(--color-accent);
  box-shadow: 0 4px 0 #b84a5e;
}

.control-btn.reset:hover {
  background: #ff7b96;
}

.control-btn.reset:active {
  box-shadow: 0 1px 0 #b84a5e;
}

.hint {
  font-size: 0.9rem;
  color: #9090a0;
  text-align: center;
}

[hidden] {
  display: none !important;
}

@media (max-width: 400px) {
  .card {
    padding: 1.5rem 1rem;
  }
  h1 {
    font-size: 1.4rem;
  }
  .status {
    flex-direction: column;
    gap: 0.25rem;
    align-items: center;
  }
  .controls {
    grid-template-columns: 1fr;
  }
  .control-btn {
    padding: 0.75rem;
    font-size: 1rem;
  }
}

const SIZE = 5;
const DIRECTIONS = ['up', 'right', 'down', 'left'];
const DIR_LABELS = { up: 'Up', right: 'Right', down: 'Down', left: 'Left' };

let robot = { x: 0, y: 0, dir: 'right' };

const board = document.getElementById('board');
const posDisplay = document.getElementById('positionDisplay');
const dirDisplay = document.getElementById('directionDisplay');

function createBoard() {
  for (let y = 0; y < SIZE; y++) {
    for (let x = 0; x < SIZE; x++) {
      const cell = document.createElement('div');
      cell.className = 'cell';
      cell.dataset.x = x;
      cell.dataset.y = y;
      cell.setAttribute('role', 'gridcell');
      cell.setAttribute('aria-label', `Cell (${x + 1},${y + 1})`);
      board.appendChild(cell);
    }
  }
}

function render() {
  document.querySelectorAll('.cell').forEach(cell => {
    cell.classList.remove('robot');
    cell.removeAttribute('data-dir');
  });
  const cell = board.querySelector(`.cell[data-x="${robot.x}"][data-y="${robot.y}"]`);
  if (cell) {
    cell.classList.add('robot');
    cell.dataset.dir = robot.dir;
  }
  posDisplay.textContent = `Position: (${robot.x + 1},${robot.y + 1})`;
  dirDisplay.textContent = `Direction: ${DIR_LABELS[robot.dir]}`;
}

function moveForward() {
  const deltas = { up: [0, -1], right: [1, 0], down: [0, 1], left: [-1, 0] };
  const [dx, dy] = deltas[robot.dir];
  const nx = robot.x + dx;
  const ny = robot.y + dy;
  if (nx >= 0 && nx < SIZE && ny >= 0 && ny < SIZE) {
    robot.x = nx;
    robot.y = ny;
  }
  render();
}

function turn(dir) {
  const idx = DIRECTIONS.indexOf(robot.dir);
  const newIdx = (idx + dir + 4) % 4;
  robot.dir = DIRECTIONS[newIdx];
  render();
}

function reset() {
  robot = { x: 0, y: 0, dir: 'right' };
  render();
}

document.getElementById('btnForward').addEventListener('click', moveForward);
document.getElementById('btnLeft').addEventListener('click', () => turn(-1));
document.getElementById('btnRight').addEventListener('click', () => turn(1));
document.getElementById('btnReset').addEventListener('click', reset);

createBoard();
render();
